for f in sorted(set(IDS)):
    p = os.path.join("images", f)
    if os.path.exists(p): continue
    req = urllib.request.Request("https://framerusercontent.com/images/" + f, headers={"User-Agent": "Mozilla/5.0"})
    try:
        open(p, "wb").write(urllib.request.urlopen(req, timeout=30).read()); print("ok  ", f)
    except Exception as e: print("FAIL", f, e)
print("done")
